52		Results  []taskResult       `json:"results"`
53	}
54	
55	type scheduledTask struct {
56		id        string
57		priority  int64
58		release   int64
59		execution int64
60		deadline  int64
61	}
62	
63	func handleAnalyze(w http.ResponseWriter, r *http.Request) {
64		if r.Method != http.MethodPost {
65			w.Header().Set("Allow", http.MethodPost)
66			writeAnalyzeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
67			return
68		}
69		var req analyzeRequest
70		if !decodeStrictJSON(w, r, &req) {
71			return
72		}
73		tasks, ok := validateAnalyzeRequest(&req)
74		if !ok {
75			writeAnalyzeError(w, http.StatusUnprocessableEntity, "validation_failed")
76			return
77		}
78		resp := simulateSchedule(tasks, *req.Horizon)
79		w.Header().Set("Content-Type", "application/json; charset=utf-8")
80		w.WriteHeader(http.StatusOK)
81		_ = json.NewEncoder(w).Encode(resp)
82	}
83	
84	func writeAnalyzeError(w http.ResponseWriter, status int, code string) {
85		http.Error(w, `{"error":{"code":"`+code+`"}}`, status)
86	}
87	
88	// decodeStrictJSON implements the request-reading rules shared by every JSON
89	// analysis endpoint. It writes the error response itself and reports whether
90	// the request may proceed; the caller therefore has no partial result to leak.
91	//
92	// Ordering: non-application/json (including a missing media type) is 415; a
93	// body larger than 1 MiB or any syntactic defect (bad syntax, trailing
94	// content, duplicate or unknown keys) is 400 invalid_json; well-formed JSON
95	// whose values do not match the target schema is 422 validation_failed.
96	func decodeStrictJSON(w http.ResponseWriter, r *http.Request, dst any) bool {
97		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
98		if err != nil || mediaType != "application/json" {
